const script=String.raw`
(function(){
 function decorate(){
  const body=document.body;
  for(const side of document.querySelectorAll('.dropso-site-sidebar,.desktop-account-sidebar')){
   const labels=['Аккаунт','Общение','Игровые режимы','События'];side.querySelectorAll('.desktop-account-group').forEach((g,i)=>g.dataset.label=labels[i]||'');
   if(side.querySelector('.dropso-redesign-collapse'))continue;
   const toggle=document.createElement('button');toggle.type='button';toggle.className='dropso-redesign-collapse';toggle.textContent='«';toggle.setAttribute('aria-label','Свернуть меню');toggle.setAttribute('aria-expanded','true');
   toggle.onclick=()=>{const collapsed=body.classList.toggle('dropso-redesign-collapsed');toggle.textContent=collapsed?'»':'«';toggle.setAttribute('aria-expanded',String(!collapsed));toggle.setAttribute('aria-label',collapsed?'Развернуть меню':'Свернуть меню')};
   side.prepend(toggle);
   if(side.classList.contains('dropso-site-sidebar')){
    const brand=document.createElement('a');brand.href='/account';brand.className='dropso-redesign-brand';brand.innerHTML='<img src="/pwa/icon/brand-logo.png" alt="">Dropso';toggle.after(brand);
   }
   const nav=side.querySelector('nav')||side.querySelector('.desktop-account-group');
   const premium=document.createElement('a');premium.className='dropso-redesign-premium';premium.href='/membership';premium.textContent='DROPSO PREMIUM';if(location.pathname==='/membership')premium.setAttribute('aria-current','page');if(nav)nav.before(premium);
   if(side.classList.contains('dropso-site-sidebar')){const balance=document.createElement('a');balance.className='dropso-redesign-balance';balance.href='/account';balance.innerHTML='<span>Баланс</span><strong>—</strong>';premium.before(balance);fetch('/api/me/economy',{cache:'no-store'}).then(r=>r.ok?r.json():null).then(d=>{if(d&&Number.isFinite(d.balance))balance.querySelector('strong').textContent=d.balance.toLocaleString('ru-RU')+' мон.'}).catch(()=>{});}
   for(const a of side.querySelectorAll('a[href="/membership"]'))if(a!==premium)a.hidden=true;
  }
 }
 function boot(){decorate();requestAnimationFrame(decorate);window.addEventListener('resize',()=>requestAnimationFrame(decorate))}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();`;
export function withDropsoRedesign(html:string,path:string){
 const page=path==='/membership'?'premium':dropsoPageKind(path);
 if(!page||['admin','landing','legal'].includes(page)||!html.includes('data-dropso-shell')||html.includes('id="dropsoRedesign"')||!/<body\\b/i.test(html))return html;
 return html.replace(/<body\\b([^>]*)>/i,(_m,attrs)=>'<body'+attrs+' data-dropso-redesign="'+page+'">').replace('</head>',()=>'<style id="dropsoRedesign">'+css+'</style></head>').replace('</body>',()=>'<script>'+script+'</script></body>');
}
